"""Round 2 decision table (hard revision). Local files only. No calendar change is made here."""
import csv, os, re, importlib.util, json
ROOT=os.path.abspath(os.path.join(os.path.dirname(__file__),'..','..','..')); os.chdir(ROOT)
vol={}
for r in csv.DictReader(open('content-strategy/blog-calendar/working/call1_processed.csv')):
    if r['search_volume'] not in ('','NOT_IN_DATAFORSEO_DB'): vol[r['keyword']]=int(r['search_volume'])
for r in csv.DictReader(open('content-strategy/blog-calendar/revision/round1_merged_raw_keywords.csv')):
    if r['search_volume']: vol.setdefault(r['keyword'],int(r['search_volume']))
for r in csv.DictReader(open('architecture/15_keyword_url_map.csv')):
    try: vol.setdefault(r['normalized_keyword'],int(float(r['search_volume'])))
    except ValueError: pass
S={r['keyword']:r for r in csv.DictReader(open('content-strategy/blog-calendar/revision/round2_serp_analysis.csv'))}
P={}
for r in csv.DictReader(open('content-strategy/blog-calendar/revision/round2_paa_questions.csv')): P.setdefault(r['keyword'],[]).append(r['paa_question'])
cal={r['blog_id']:r for r in csv.DictReader(open('content-strategy/blog-calendar/blog_content_calendar.csv')) if r['content_status']!='UNUSED_SLOT'}
def v(k): return f"{k} ({vol.get(k,'n/a')})"
def serp(k):
    s=S.get(k); 
    return f"{s['serp_intent_verified']} | {s['top10_page_types']} | shopping features: {s['shopping_features']}" if s else 'not SERP-checked'
def aio(k):
    s=S.get(k); 
    return f"{'PRESENT' if s['ai_overview']=='True' else 'ABSENT'}: {s['aio_section_headings']}" if s else ''
def paa(k): return ' | '.join(P.get(k,[])[:6])
D=[]
def d(bid, action, primary, candidates, fit, conflict, reason, serp_kw=None, new_title=''):
    serp_kw=serp_kw or primary
    D.append({'blog_id':bid,'current_title':cal[bid]['blog_title_working'] if bid in cal else new_title,'recommended_action':action,
      'current_primary':v(cal[bid]['primary_keyword']) if bid in cal else '', 'recommended_primary':v(primary),
      'stronger_candidates_reviewed':'; '.join(v(c) for c in candidates),
      'serp_intent_and_composition':serp(serp_kw),'ai_overview_structure':aio(serp_kw),'paa_questions':paa(serp_kw),
      'blog_fit':fit,'ownership_cannibalization':conflict,'reason':reason})
